targets.expr:
(
  sum by (instance) (
    hh3cEntityExtMacAddressCount{job=~"$job", region=~"$region", brand=~"$brand", role=~"$role", instance=~"$device_ip"}
  )
)
/
(
  sum by (instance) (
    hh3cMaxMacLearnRange{job=~"$job", region=~"$region", brand=~"$brand", role=~"$role", instance=~"$device_ip"}
  )
)
* on(instance) group_left(sysName) sysName{sysName!=""}

(
    # 主计算分支：值>0时的正确计算
    10 * log10(
        ((hh3cTransceiverRcvPwrHiWarn{job=~"$job", region=~"$region", brand=~"$brand", role=~"$role", instance=~"$device_ip"} > 0) / 1000)
    )
    # 关联sysName标签
    * on(instance) group_left(sysName) sysName{sysName!=""}
)
or 
(
    # 零值分支：值<=0时返回0并携带标签
    (hh3cTransceiverRcvPwrHiWarn{job=~"$job", region=~"$region", brand=~"$brand", role=~"$role", instance=~"$device_ip"} <= 0)
    # 关联标签并强制返回0
    * on(instance) group_left(sysName) sysName{sysName!=""} 
    * 0 
)

(
    # 主计算分支：值>0时的正确计算
    10 * log10(
        ((hh3cTransceiverRcvPwrLoWarn{job=~"$job", region=~"$region", brand=~"$brand", role=~"$role", instance=~"$device_ip"} > 0) / 1000)
